```javascript
let Hearts = [];

function setup() {
  createCanvas(600, 600, WEBGL);
  angleMode(DEGREES);
  Hearts.push(new Heart());
}

function draw() {
  background(220);
  rotateY(frameCount * 0.01);
  translate(0, 0, -200);
  for (let heart of Hearts) {
    heart.update();
    heart.draw();
  }
}

class Heart {
  constructor() {
    this.radius = 100;
    this.angle = 0;
  }

  update() {
    this.angle += 2;
  }

  draw() {
    stroke(255, 0, 0);
    noFill();
    beginShape();
    for (let i = 0; i < 360; i += 1) {
      let r = this.radius * (0.5 + 0.4 * sin(this.angle + i * 0.5));
      let x = r * sin(i * 0.0175);
      let z = r * cos(i * 0.0175);
      vertex(x, 0, z);
    }
    for (let i = 359; i >= 0; i -= 1) {
      let r = this.radius * (0.5 + 0.4 * sin(this.angle + i * 0.5));
      let x = r * sin(i * 0.0175);
      let z = r * cos(i * 0.0175);
      vertex(x, 0, z);
    }
    endShape(CLOSE);
  }
}
```

