Here is an implementation of a queue data structure using two stacks in Python:

```
class Stack:
    def __init__(self):
        self.stack = []

    def push(self, value):
        self.stack.append(value)

    def pop(self):
        if not self.is_empty():
            return self.stack.pop()
        else:
            return None

    def is_empty(self):
        return not bool(self.stack)


class Queue:
    def __init__(self):
        self.stack_newest_on_top = Stack()
        self.stack_oldest_on_top = Stack()

    def enqueue(self, value):
        self.stack_newest_on_top.push(value)

    def dequeue(self):
        if self.stack_oldest_on_top.is_empty():
            while not self.stack_newest_on_top.is_empty():
                self.stack_oldest_on_top.push(self.stack_newest_on_top.pop())
        return self.stack_oldest_on_top.pop()

    def is_empty(self):
        return self.stack_newest_on_top.is_empty() and self.stack_oldest_on_top.is_empty()


# Test the queue
q = Queue()
q.enqueue(1)
q.enqueue(2)
q.enqueue(3)

print(q.dequeue())  # Output: 1
print(q.dequeue())  # Output: 2
print(q.dequeue())  # Output: 3
print(q.is_empty())  # Output: True
```

