```csharp
using System;
using System.Net;
using System.Net.Http;
using System.IO;

class HelloServer
{
    static void Main(string[] args)
    {
        HttpListener listener = new HttpListener();
        listener.Prefixes.Add("http://localhost:8080/hello");
        listener.Start();

        Console.WriteLine("Serveur démarré. Appuyez sur Entrée pour terminer.");

        while (true)
        {
            HttpListenerContext context = listener.GetContext();
            HttpListenerRequest request = context.Request;

            using (StreamWriter writer = new StreamWriter(context.Response.OutputStream))
            {
                writer.Write("Hello");
            }

            context.Response.StatusCode = 200;
            context.Response.ContentType = "text/plain";
            context.Response.Close();
        }
    }
}
```
Ce code crée un objet `HttpListener` et définit un prefix pour indiquer que le serveur écoute les requêtes sur l'adresse `http://localhost:8080/hello`. Il commence ensuite à écouter les requêtes avec la méthode `Start()`.

