#include <stdio.h>
#include <jni.h>

static jvmtiEnv* jvmti_env = NULL;

JNIEXPORT jint JNICALL Agent_OnLoad(JavaVM *jvm, char *options) {
    // Initialize JVMTI environment
    jvmti_env = (jvmtiEnv*)(*jvm)->GetEnv(jvm, JVMTI_VERSION_1_0);
    if (jvmti_env == NULL) {
        return -1;
    }

    // Set the transform hook
    jvmti_env->SetEventHooks2(jvmti_env, (jvmtiEventCallbacks*)transform_hook);

    return 0;
}

static jvmtiEventCallbacks transform_hook = {
    // Method to handle class loading
    .ClassLoad = (jvmtiClassLoadEventCallbacks *)ClassLoadHook,
    // Method to handle method invocation
    .MethodInvoke = (jvmtiMethodInvokeEventCallbacks *)MethodInvokeHook,
};

// Handle class loading event
JNIEXPORT void JNICALL Java:jvmtiagenttransformsClassLoadHook(JNIEnv *env, jobject, jclass clazz) {
    // You can transform the class here
