// Handle method invocation event
JNIEXPORT void JNICALL Java:jvmtiagenttransformsMethodInvokeHook(JNIEnv *env, jobject, jobject method, jobjectArray args) {
    // You can transform the method here
    printf("Method invoked: %s\n", env->GetMethodName(method));
